/**
 * Calculate the discount amount for a line (tier/explicit + bulk).
 * Bulk discount: 2.5% on amount remaining after first discount, for qty >= 10.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  const firstDiscount = roundCents(total * discountPercent / 100);

  let bulkDiscount = 0;
  if (line.qty >= 10) {
    const amountAfterFirstDiscount = total - firstDiscount;
    bulkDiscount = roundCents(amountAfterFirstDiscount * 0.025);
  }

  return firstDiscount + bulkDiscount;
}

