  const line = { qty: 9, unitPrice: 9500, discountPercent: 10 };
  const total = lineTotal(line);
  const expected = Math.round(total * 0.1);
  assert.equal(lineDiscount(line), expected);
});

test('lineDiscount with qty >= 10 includes bulk discount', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 10 };
  const total = lineTotal(line);
  const firstDiscount = Math.round(total * 0.1);
  const afterFirst = total - firstDiscount;
  const bulkDiscount = Math.round(afterFirst * 0.025);
  const expected = firstDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expected);
});

test('lineDiscount with no discountPercent and qty < 10', () => {
  const line = { qty: 9, unitPrice: 9500 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount with no discountPercent and qty >= 10 has bulk discount', () => {
  const line = { qty: 10, unitPrice: 9500 };
  const total = lineTotal(line);
  const bulkDiscount = Math.round(total * 0.025);
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount with 0 discountPercent and qty < 10', () => {
  const line = { qty: 9, unitPrice: 9500, discountPercent: 0 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount with 0 discountPercent and qty >= 10 has bulk discount', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = Math.round(total * 0.025);
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount bulk discount threshold is 10', () => {
  const line9 = { qty: 9, unitPrice: 10000 };
  const line10 = { qty: 10, unitPrice: 10000 };
  const discount9 = lineDiscount(line9);
  const discount10 = lineDiscount(line10);
  assert.equal(discount9, 0);
  assert.ok(discount10 > 0);
});

test('lineVAT calculated on amount after all discounts', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const base = total - discount;
  const vat = Math.round(base * 0.21);
  assert.equal(lineVAT(line), vat);
});

test('lineVAT with 9 percent rate', () => {
  const line = { qty: 10, unitPrice: 1250, vatRate: 9 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const base = total - discount;
  const vat = Math.round(base * 0.09);
  assert.equal(lineVAT(line), vat);
});

test('lineVAT with 0 percent rate', () => {
  const line = { qty: 10, unitPrice: 35000, vatRate: 0 };
  assert.equal(lineVAT(line), 0);
});

