  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 95000);
  const expectedDiscount = Math.round(95000 * 0.025);
  assert.equal(result.discount, expectedDiscount);
  const base = 95000 - expectedDiscount;
  const expectedVAT = Math.round(base * 0.21);
  assert.equal(result.vat, expectedVAT);
